# Then see which ones got filled with 3s

def find_0_components(input_grid):
    rows, cols = len(input_grid), len(input_grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    def bfs(start_r, start_c):
        component = []
        queue = [(start_r, start_c)]
        visited[start_r][start_c] = True
        current_loc = set([(start_r, start_c)])
        # Use max iterations to avoid infinite loop
        import collections
        queue = collections.deque([start_r, start_c])
        while queue:
            r, c = queue.popleft()
            component.append((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and input_grid[nr][nc] == 0:
                    visited[nr][nc] = True
                    queue.append((nr, nc))
        return component

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and input_grid[r][c] == 0:
                comp = bfs(r, c)
                components.append(comp)

    return components

